    SpanWithTypeC(CARB_ABI* getAttributeMGpuMemType)(StageReaderWriterId stageId,
                                                     const PXR_NS::SdfPath& path,
                                                     const PXR_NS::TfToken& attrNameId,
                                                     PtrToPtrKind wherePtr,
                                                     int deviceId);

